export * as ShellScan from "./scan.js";
export type OpaqueReason = "command-substitution" | "compound-command" | "dynamic-command-name" | "dynamic-execution" | "heredoc" | "invalid-redirect" | "invalid-structure" | "unterminated-escape" | "unterminated-quote";
type Command = {
    resource: string;
    words: string[];
    rawWords: string[];
    wordEnds?: number[];
    statementHead?: true;
    declaration?: true;
    redirectWordCount?: number;
};
export type Result = {
    kind: "scanned";
    commands: Command[];
} | {
    kind: "opaque";
    reason: OpaqueReason;
};
export type Dialect = "bash" | "zsh" | "posix";
export declare function scan(input: string, dialect?: Dialect): Result;
export declare function scanPowerShell(input: string): Result;
